1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.rest.validation.IdentityKeyNormalizer;
12	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
13	
14	import java.time.LocalDate;
15	import java.time.Period;
16	import java.time.temporal.ChronoUnit;
17	import java.util.Collection;
18	import java.util.List;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
27	    @Mapping(target = "initials", expression = "java(initials(owner))")
28	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
29	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
30	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
31	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
32	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
33	    @Mapping(target = "locality", expression = "java(locality(owner))")
34	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
35	    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
36	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
37	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
38	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
39	    OwnerDto toOwnerDto(Owner owner);
40	
41	    Owner toOwner(OwnerDto ownerDto);
42	
43	    /**
44	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
45	     */
46	    default String displayName(Owner owner) {
47	        if (owner == null) {
48	            return null;
49	        }
50	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
51	        String firstName = owner.getFirstName() == null ? "" : owner.getFirstName();
52	        return lastName + ", " + firstName;
53	    }
54	
55	    /**
56	     * Returns the upper-cased first letters of firstName and lastName,
57	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
58	     */
59	    default String initials(Owner owner) {
60	        if (owner == null) {
61	            return null;
62	        }
63	        StringBuilder sb = new StringBuilder();
64	        String firstName = owner.getFirstName();
65	        String lastName = owner.getLastName();
66	        if (firstName != null && !firstName.isEmpty()) {
67	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
68	        }
69	        if (lastName != null && !lastName.isEmpty()) {
70	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
71	        }
72	        return sb.toString();
73	    }
74	
75	    /**
76	     * Formats the owner's stored E.164 {@code telephone} for human display: the country code,
77	     * a space, and the national digits grouped in threes separated by spaces, e.g.
78	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}. The raw {@code telephone} is
79	     * left unchanged in E.164 form.
80	     */
81	    default String telephoneDisplay(Owner owner) {
82	        if (owner == null) {
83	            return null;
84	        }
85	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
86	    }
87	
88	    /**
89	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
90	     * code, the literal {@code '-M'}, and the last two digits of the registrationDate year.
91	     * Returns {@code null} unless both the customer code and registration date are present.
92	     */
93	    default String membershipNumber(Owner owner) {
94	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
95	            return null;
96	        }
97	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
98	        return owner.getCustomerCode() + "-M" + yy;
99	    }
100	
101	    /**
102	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
103	     * contained in the {@code customerCode}. Returns {@code null} when no customer code is present.
104	     */
105	    default Integer checkDigit(Owner owner) {
106	        if (owner == null || owner.getCustomerCode() == null) {
107	            return null;
108	        }
109	        String code = owner.getCustomerCode();
110	        int sum = 0;
111	        boolean dbl = true;
112	        for (int i = code.length() - 1; i >= 0; i--) {
113	            char c = code.charAt(i);
114	            if (c < '0' || c > '9') {
115	                continue;
116	            }
117	            int d = c - '0';
118	            if (dbl) {
119	                d *= 2;
120	                if (d > 9) {
121	                    d -= 9;
122	                }
123	            }
124	            sum += d;
125	            dbl = !dbl;
126	        }
127	        return (10 - (sum % 10)) % 10;
128	    }
129	
130	    /**
131	     * Computes the owner's membership points. Starts at {@code 0}; adds {@code 2} when an email
132	     * address is present; adds {@code 1} when the owner has no namesakes (namesakeCount is 0);
133	     * adds {@code 2} when the owner belongs to a household of {@code 3} or more members; adds
134	     * {@code 3} when the owner's tenure exceeds 365 days.
135	     */
136	    default Integer membershipPoints(Owner owner) {
137	        if (owner == null) {
138	            return null;
139	        }
140	        int points = 0;
141	        String email = owner.getEmail();
142	        if (email != null && !email.isEmpty()) {
143	            points += 2;
144	        }
145	        Integer namesakeCount = owner.getNamesakeCount();
146	        if (namesakeCount != null && namesakeCount == 0) {
147	            points += 1;
148	        }
149	        Integer householdMemberCount = owner.getHouseholdMemberCount();
150	        if (householdMemberCount != null && householdMemberCount >= 3) {
151	            points += 2;
152	        }
153	        LocalDate registrationDate = owner.getRegistrationDate();
154	        if (registrationDate != null
155	                && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
156	            points += 3;
157	        }
158	        return points;
159	    }
160	
161	    /**
162	     * Derives the owner's numeric membership level from {@link #membershipPoints(Owner)}: level
163	     * {@code 1} for {@code 0-1} points, level {@code 2} for {@code 2-3} points, level {@code 3}
164	     * for {@code 4-5} points, and level {@code 4} for {@code 6} or more points.
165	     */
166	    default Integer membershipLevel(Owner owner) {
167	        if (owner == null) {
168	            return null;
169	        }
170	        int points = membershipPoints(owner);
171	        if (points <= 1) {
172	            return 1;
173	        }
174	        if (points <= 3) {
175	            return 2;
176	        }
177	        if (points <= 5) {
178	            return 3;
179	        }
180	        return 4;
181	    }
182	
183	    /**
184	     * Derives the owner's locality (region) from the {@code customerCode}, whose form is
185	     * {@code '<REGION>-<HASH8>'}: the locality is the {@code REGION} segment before the first
186	     * hyphen. Returns {@code "UNKNOWN"} when the owner has no customer code yet.
187	     */
188	    default String locality(Owner owner) {
189	        if (owner == null) {
190	            return null;
191	        }
192	        String code = owner.getCustomerCode();
193	        if (code == null) {
194	            return "UNKNOWN";
195	        }
196	        int dash = code.indexOf('-');
197	        return dash >= 0 ? code.substring(0, dash) : code;
198	    }
199	
200	    /**
201	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
202	     * on its registration day at creation time). A {@code null} stored value is treated as
203	     * {@code false}, so the field is always present in the response.
204	     */
